import{_ as i,o as e,c as a,a4 as t}from"./chunks/framework.vNSRaLQv.js";const p=JSON.parse('{"title":"CC-Switch + Claude/Codex 折腾教训记录","description":"","frontmatter":{"title":"CC-Switch + Claude/Codex 折腾教训记录","date":"2026-08-15T00:00:00.000Z"},"headers":[],"relativePath":"posts/ccswitch_lessons.md","filePath":"posts/ccswitch_lessons.md"}'),l={name:"posts/ccswitch_lessons.md"};function c(o,s,d,n,h,r){return e(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="cc-switch-claude-codex-折腾教训记录" tabindex="-1">CC-Switch + Claude/Codex 折腾教训记录 <a class="header-anchor" href="#cc-switch-claude-codex-折腾教训记录" aria-label="Permalink to &quot;CC-Switch + Claude/Codex 折腾教训记录&quot;">​</a></h1><h2 id="_2026-08-15-大翻车总结" tabindex="-1">2026-08-15 大翻车总结 <a class="header-anchor" href="#_2026-08-15-大翻车总结" aria-label="Permalink to &quot;2026-08-15 大翻车总结&quot;">​</a></h2><h3 id="_1-数据备份的致命教训" tabindex="-1">1. 数据备份的致命教训 <a class="header-anchor" href="#_1-数据备份的致命教训" aria-label="Permalink to &quot;1. 数据备份的致命教训&quot;">​</a></h3><ul><li><strong><code>mv A A.bak</code> 之后再 <code>mv A.bak A</code>，A.bak 就没了，不是双份</strong></li><li>还原 ≠ 备份，改名不是复制</li><li><code>rm -rf</code> 前必须确认 <strong>有没有独立的、不重叠的备份</strong></li><li>NFS 上删除的文件在客户端无法用 extundelete 恢复，只有服务器端才有机会</li></ul><h3 id="_2-代理端口跨机器陷阱" tabindex="-1">2. 代理端口跨机器陷阱 <a class="header-anchor" href="#_2-代理端口跨机器陷阱" aria-label="Permalink to &quot;2. 代理端口跨机器陷阱&quot;">​</a></h3><ul><li>cc-switch 写 <code>settings.json</code> 时，代理地址写的是 <code>127.0.0.1:15721</code>（它假设工具和代理在同一台机器）</li><li>实际场景：工具跑在 a1，代理跑在 hi-box (192.168.31.82)，<code>127.0.0.1</code> 指 a1 本机 → 连不上</li><li>每次切 provider，cc-switch 会 <strong>覆盖</strong> <code>settings.json</code>，手改的地址被重置回 <code>127.0.0.1</code></li><li>解决思路：<strong>本地 socat 转发 <code>127.0.0.1:15721 → 192.168.31.82:15721</code></strong>，让 Claude 以为自己连的是本机代理</li></ul><h3 id="_3-socat-tcp-转发的-systemd-服务" tabindex="-1">3. socat TCP 转发的 systemd 服务 <a class="header-anchor" href="#_3-socat-tcp-转发的-systemd-服务" aria-label="Permalink to &quot;3. socat TCP 转发的 systemd 服务&quot;">​</a></h3><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">[</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">Unit</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">]</span></span>
<span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">Description</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">=</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">Forward 127.0.0.1:15721 -&gt; 192.168.31.82:15721</span></span>
<span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">After</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">=</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">network.target</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">[</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">Service</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">]</span></span>
<span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">Type</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">=</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">simple</span></span>
<span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">ExecStart</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">=</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">/usr/bin/socat TCP-LISTEN:15721,</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">bind</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">=</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">127.0.0.1,fork,reuseaddr,keepalive TCP:192.168.31.82:15721</span></span>
<span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">Restart</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">=</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">always</span></span>
<span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">RestartSec</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">=</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">3</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">[</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">Install</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">]</span></span>
<span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">WantedBy</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">=</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">multi-user.target</span></span></code></pre></div><p>放在 <code>/etc/systemd/system/claude-proxy-forward.service</code>。<code>fork</code> 是关键参数（每个连接开子进程，互不阻塞）。</p><h3 id="_4-cc-switch-web-代理-15721-启动机制不明" tabindex="-1">4. cc-switch-web 代理 15721 启动机制不明 <a class="header-anchor" href="#_4-cc-switch-web-代理-15721-启动机制不明" aria-label="Permalink to &quot;4. cc-switch-web 代理 15721 启动机制不明&quot;">​</a></h3><ul><li><code>systemctl restart cc-switch-web</code> 只起 Web UI (17666)，<strong>不起代理 (15721)</strong></li><li>代理需要用户手动在 Web 界面点某个按钮/开关，具体入口没找到</li><li>cc-switch-web 是单个二进制，无日志（<code>StandardOutput=null</code>），journalctl 查不到</li><li>17666 和 15721 是同一个进程的不同端口，但 15721 不是启动时自动开的</li></ul><h3 id="_5-cc-switch-web-v0-1-0-二进制有-bug-—-代理模块必死" tabindex="-1">5. cc-switch-web v0.1.0 二进制有 bug — 代理模块必死 <a class="header-anchor" href="#_5-cc-switch-web-v0-1-0-二进制有-bug-—-代理模块必死" aria-label="Permalink to &quot;5. cc-switch-web v0.1.0 二进制有 bug — 代理模块必死&quot;">​</a></h3><ul><li><strong>根因</strong>：代理模块（15721）处理到某种请求时调用 <code>abort()</code> 自杀，<code>dmesg</code> 看到 <code>status=6/ABRT</code></li><li>第一次崩得很快（49秒），第二次撑了16分钟，说明不是启动时必然崩，而是<strong>处理请求时触发 bug</strong></li><li><code>NRestarts=0</code> — systemd 没设 <code>Restart=always</code>，崩了不会自动重启</li><li>Web UI（17666）模块没问题，只有代理模块有问题</li><li><strong>结论</strong>：v0.1.0 二进制本身有问题，不是配置/网络/地址问题</li></ul><h3 id="_6-cc-switch-配置优先级-从高到低" tabindex="-1">6. cc-switch 配置优先级（从高到低） <a class="header-anchor" href="#_6-cc-switch-配置优先级-从高到低" aria-label="Permalink to &quot;6. cc-switch 配置优先级（从高到低）&quot;">​</a></h3><ol><li><code>~/.claude/settings.json</code> → <code>env.ANTHROPIC_BASE_URL</code>（<strong>cc-switch 写的地方，最高优先级</strong>）</li><li><code>~/.claude.json</code> → <code>anthropic_base_url</code>（手改的地方，但被 settings.json 覆盖）</li><li>环境变量 / 系统默认</li></ol><ul><li>cc-switch 每次切 provider <strong>只覆盖 settings.json</strong>，所以改 .claude.json 没用</li><li><code>.claude.json</code> 是全局配置，<code>settings.json</code> 是项目级配置</li></ul><h3 id="_7-僵尸进程坑" tabindex="-1">7. 僵尸进程坑 <a class="header-anchor" href="#_7-僵尸进程坑" aria-label="Permalink to &quot;7. 僵尸进程坑&quot;">​</a></h3><ul><li>之前跑 <code>/opt/cc-switch-web/cc-switch-web version</code> 命令，pid 7523 没退出，占了 17666 端口</li><li>真服务启动不了，<code>systemctl restart</code> 也没用，需要 <code>kill -9</code> 清掉</li><li>类似的 <code>--help</code> 命令也可能留下僵尸进程（pid 5233）</li><li><strong>经验</strong>：不要在服务器上跑会启动完整二进制再退出的命令</li></ul><h3 id="_8-cc-switch-接管工具的机制" tabindex="-1">8. CC-Switch 接管工具的机制 <a class="header-anchor" href="#_8-cc-switch-接管工具的机制" aria-label="Permalink to &quot;8. CC-Switch 接管工具的机制&quot;">​</a></h3><h3 id="_8-cc-switch-接管工具的机制-1" tabindex="-1">8. CC-Switch 接管工具的机制 <a class="header-anchor" href="#_8-cc-switch-接管工具的机制-1" aria-label="Permalink to &quot;8. CC-Switch 接管工具的机制&quot;">​</a></h3><ul><li>数据库 (<code>/mnt/shared/.cc-switch/cc-switch.db</code>) 存所有 provider 配置</li><li>切 provider 时把 <code>settings_config</code> 表里的配置拼合后<strong>写入工具实际配置文件</strong></li><li>Claude: 写 <code>settings.json</code> 的 <code>ANTHROPIC_BASE_URL</code> + <code>ANTHROPIC_AUTH_TOKEN</code></li><li>Codex: 拼合 <code>config.toml</code> + <code>OPENAI_API_KEY</code></li><li>可选代理层（15721）做统计/日志/故障切换，<code>proxy_config.enabled</code> 控制</li></ul><h3 id="_9-当前最终状态-2026-08-15" tabindex="-1">9. 当前最终状态（2026-08-15） <a class="header-anchor" href="#_9-当前最终状态-2026-08-15" aria-label="Permalink to &quot;9. 当前最终状态（2026-08-15）&quot;">​</a></h3><ul><li><code>/mnt/shared/.claude</code> — 已还原，清理后 756K（嵌套 <code>.claude/</code> Windows 残留已删）</li><li><code>/mnt/shared/.codex</code> — 已还原，历史已清理（416M → 21M）</li><li>cc-switch-web — 17666 起，15721 未开（代理模块有 bug，开了就崩）</li><li>本机 socat 转发 — 已卸载（最终弃用代理方案）</li><li>最终方案：<strong>放弃代理，走直连</strong></li><li>本机 <code>.claude.json</code> 仍有 <code>192.168.31.82:15721</code>（不影响，优先级低于 settings.json）</li></ul><h3 id="_10-如果重来的话" tabindex="-1">10. 如果重来的话 <a class="header-anchor" href="#_10-如果重来的话" aria-label="Permalink to &quot;10. 如果重来的话&quot;">​</a></h3><ul><li>数据备份用 <code>cp -a</code> 到独立路径，不是 <code>mv</code></li><li><code>rm -rf</code> 前先问：这份数据有没有独立副本？</li><li>代理跨机器场景，先确认端口绑定地址和工具运行机器的关系</li><li>查日志时先看 <code>StandardOutput</code> 和 <code>ExecStart</code>，很多服务不写日志</li><li>查进程崩溃先看 <code>dmesg -T | tail</code>，比 journalctl 更可靠（很多服务不吃 journal）</li><li><code>status=6/ABRT</code> = 程序主动调用 abort() 自杀，不是 OOM 不是 segfault，代码 bug</li><li>代理跨机器之前，先确认 <code>listen_address</code> 绑定的是不是工具所在机器的网卡 IP</li></ul>`,25)])])}const g=i(l,[["render",c]]);export{p as __pageData,g as default};
